SELECT U.id_usuario AS "IdUsuario",U.id_empresa AS "IdEmpresa",fecha_vigencia AS "FechaVigencia",S.id_entidad_sso AS "IdEntidadSSO",SSO.redirect_url AS "RedirectURL",U.id_estado AS "IdEstado",U.codigo_usuario AS "CodigoUsuario",U.id_entidad AS "IdEntidad",U.codigo_menu AS "CodigoMenu",EMP.id_empleado AS "IdEmpleado",CLI.id_cliente AS "IdCliente" FROM t_pla_acc_sesion S INNER JOIN t_pla_acc_usuario U on U.id_usuario = S.id_usuario LEFT JOIN t_pla_acc_configuracion_sso SSO on SSO.id_entidad = S.id_entidad_sso LEFT JOIN t_socneg_emp_empleado EMP ON U.tipo_entidad = 'EMP' AND U.id_entidad = EMP.id_empleado LEFT JOIN t_socneg_cli_cliente CLI ON U.tipo_entidad = 'CLI' AND U.id_entidad = CLI.id_cliente WHERE id_token_sesion = :IdTokenSesion AND token_valido = 'S'